# Generated by packaging/homebrew/formula.sh in tarannum22/watermelon-pgp; changes here are overwritten.
class WatermelonPgp < Formula
  desc "Self-hosted OpenPGP key management and folder encryption jobs, with a web UI"
  homepage "https://tarannum22.github.io/watermelon-pgp/"
  license any_of: ["MIT", "Apache-2.0"]

  on_macos do
    on_arm do
      url "https://github.com/tarannum22/watermelon-pgp/releases/download/v0.2.0/watermelon-pgp-v0.2.0-aarch64-apple-darwin.tar.gz"
      sha256 "17c8036a0c940c1f2fbf6255e32b4ed9dcf7ba9388cc14fd7d259464fb9d3501"
    end
    on_intel do
      url "https://github.com/tarannum22/watermelon-pgp/releases/download/v0.2.0/watermelon-pgp-v0.2.0-x86_64-apple-darwin.tar.gz"
      sha256 "f4640ee2aeea3fbc71ac4b44ab27eddb13b210d7907363fb7483709b796d432f"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/tarannum22/watermelon-pgp/releases/download/v0.2.0/watermelon-pgp-v0.2.0-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "503fd8de968a38f116e74e1fc5cbbf51a5e2011617881c60c4f69fd696511439"
    end
    on_intel do
      url "https://github.com/tarannum22/watermelon-pgp/releases/download/v0.2.0/watermelon-pgp-v0.2.0-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "aaff6000bdad1d731152c3e17c20534f3974e2ee7688dd107d6c0907227e69a7"
    end
  end

  def install
    bin.install "watermelon"
    doc.install "README.md", "CHANGELOG.md", "docs"
    pkgshare.install "contrib"
  end

  service do
    run [opt_bin/"watermelon", "serve"]
    environment_variables WATERMELON_DATA_DIR: var/"watermelon"
    keep_alive crashed: true
    log_path var/"log/watermelon.log"
    error_log_path var/"log/watermelon.log"
  end

  def caveats
    <<~EOS
      Create the database, master key and admin password once:
        watermelon --data-dir #{var}/watermelon init

      Then run it in the background (web UI on http://127.0.0.1:8080):
        brew services start watermelon-pgp
      or in the foreground:
        watermelon --data-dir #{var}/watermelon serve

      Back up #{var}/watermelon/master.key separately: without it the
      secret keys in the database cannot be recovered.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/watermelon --version")
    ENV["WATERMELON_DATA_DIR"] = testpath/"data"
    pipe_output("#{bin}/watermelon --passphrase-stdin init", "a long test password\n", 0)
    assert_path_exists testpath/"data/watermelon.db"
    assert_match "Created customer", shell_output("#{bin}/watermelon customer add ACME")
  end
end
